import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Mock данные больше не используются - все данные загружаются из API

  useEffect(() => {
    // Проверка аутентификации при загрузке приложения
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('authToken');
        if (token) {
          // Если есть токен, но нет данных пользователя, очищаем токен
          // Пользователь должен войти заново для получения актуальных данных
          localStorage.removeItem('authToken');
          setUser(null);
          setIsAuthenticated(false);
        } else {
          setUser(null);
          setIsAuthenticated(false);
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        setUser(null);
        setIsAuthenticated(false);
      } finally {
        setLoading(false);
      }
    };

    checkAuth();
  }, []);

  const login = async (email, password) => {
    setLoading(true);
    try {
      // Отправляем запрос на сервер
      const response = await fetch('http://localhost:3002/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success) {
        localStorage.setItem('authToken', data.token);
        
        // Преобразуем данные пользователя из БД в формат приложения
        const userData = {
          id: data.user.id,
          name: data.user.name,
          email: data.user.email,
          avatar: data.user.avatarUrl,
          position: data.user.position,
          company: data.user.company,
          location: data.user.location,
          status: data.user.status,
          skills: data.user.skills || [],
          interests: data.user.interests || [],
          about: data.user.bio,
          connections: 42, // Можно получать из БД
          views: 128, // Можно получать из БД
          friends: data.user.id === 1 ? [
            // Друзья для Александра Петрова (ID: 1)
            { id: 2, name: "Мария Сидорова", position: "HR Manager", company: "HR Solutions", avatar: "https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face" },
            { id: 3, name: "Дмитрий Козлов", position: "Full-stack Developer", company: "AI Solutions", avatar: "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face" },
            { id: 4, name: "Анна Волкова", position: "UX/UI Designer", company: "Design Studio", avatar: "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150&h=150&fit=crop&crop=face" },
            { id: 5, name: "Сергей Морозов", position: "DevOps Engineer", company: "CloudTech", avatar: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&h=150&fit=crop&crop=face" },
            { id: 6, name: "Елена Новикова", position: "Marketing Manager", company: "Digital Agency", avatar: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150&h=150&fit=crop&crop=face" },
            { id: 7, name: "Игорь Лебедев", position: "Mobile Developer", company: "MobileDev", avatar: "https://images.unsplash.com/photo-1507591064344-4c6ce005b128?w=150&h=150&fit=crop&crop=face" },
            { id: 8, name: "Ольга Соколова", position: "Data Analyst", company: "DataCorp", avatar: "https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?w=150&h=150&fit=crop&crop=face" },
            { id: 9, name: "Павел Кузнецов", position: "Backend Developer", company: "Backend Solutions", avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face" },
            { id: 10, name: "Татьяна Попова", position: "QA Engineer", company: "Quality Assurance", avatar: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&h=150&fit=crop&crop=face" }
          ] : [], // Для других пользователей пустой список
          // Добавляем дополнительные поля для профиля
          workExperience: [
            {
              position: data.user.position || 'Специалист',
              company: data.user.company || 'Компания',
              period: 'Текущая позиция',
              duration: 'Активно',
              description: data.user.bio || 'Описание опыта работы'
            }
          ],
          education: [
            {
              faculty: 'Высшее образование',
              university: 'Университет',
              period: 'Годы обучения',
              degree: 'Степень',
              specialization: 'Специализация'
            }
          ],
          contact: {
            email: data.user.email,
            phone: '+7 (999) 000-00-00',
            telegram: '@username'
          },
          preferences: {
            notifications: true,
            emailUpdates: true,
            profileVisibility: 'public',
            jobAlerts: true
          }
        };

        setUser(userData);
        setIsAuthenticated(true);
        return { success: true };
      } else {
        throw new Error(data.error || 'Ошибка авторизации');
      }
    } catch (error) {
      console.error('Ошибка авторизации:', error);
      console.error('Детали ошибки:', {
        message: error.message,
        stack: error.stack,
        name: error.name
      });
      return { success: false, error: error.message };
    } finally {
      setLoading(false);
    }
  };

  const register = async (userData) => {
    setLoading(true);
    try {
      // Отправляем запрос на новый API
      const response = await fetch('http://localhost:3002/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(userData),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      
      if (data.success) {
        // Сохраняем токен
        localStorage.setItem('authToken', data.token);
        
        // Преобразуем данные пользователя в формат приложения
        const newUser = {
          id: data.user.id,
          name: data.user.name,
          email: data.user.email,
          avatar: data.user.avatarUrl || '',
          position: data.user.position || '',
          company: data.user.company || '',
          location: data.user.location || '',
          status: data.user.status || 'Открыт к предложениям',
          skills: data.user.skills || [],
          interests: data.user.interests || [],
          about: data.user.bio || '',
          connections: 0,
          views: 0,
          friends: [],
          workExperience: [
            {
              position: data.user.position || 'Специалист',
              company: data.user.company || 'Компания',
              period: 'Текущая позиция',
              duration: 'Активно',
              description: data.user.bio || 'Описание опыта работы'
            }
          ],
          education: [
            {
              faculty: 'Высшее образование',
              university: 'Университет',
              period: 'Годы обучения',
              degree: 'Степень',
              specialization: 'Специализация'
            }
          ],
          contact: {
            email: data.user.email,
            phone: data.user.phone || '',
            telegram: '@username'
          },
          preferences: {
            notifications: true,
            emailUpdates: true,
            profileVisibility: 'public',
            jobAlerts: true
          }
        };
        
        setUser(newUser);
        setIsAuthenticated(true);
        return { success: true };
      } else {
        throw new Error(data.error || 'Ошибка регистрации');
      }
    } catch (error) {
      console.error('Registration error:', error);
      return { success: false, error: error.message };
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('authToken');
    setUser(null);
    setIsAuthenticated(false);
  };

  const updateProfile = async (profileData) => {
    setLoading(true);
    try {
      // Симуляция API запроса
      await new Promise(resolve => setTimeout(resolve, 500));
      
      const updatedUser = {
        ...user,
        ...profileData,
        profile: {
          ...user.profile,
          ...profileData.profile
        }
      };
      
      setUser(updatedUser);
      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    } finally {
      setLoading(false);
    }
  };

  const value = {
    user,
    loading,
    isAuthenticated,
    login,
    register,
    logout,
    updateProfile
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
