import React from 'react';

const Avatar = ({ 
  src, 
  alt, 
  size = 'md', 
  fallback,
  className = '',
  online = false,
  ...props 
}) => {
  const sizes = {
    xs: 'h-6 w-6',
    sm: 'h-8 w-8',
    md: 'h-10 w-10',
    lg: 'h-12 w-12',
    xl: 'h-16 w-16',
    '2xl': 'h-20 w-20'
  };
  
  const statusSizes = {
    xs: 'h-1.5 w-1.5',
    sm: 'h-2 w-2', 
    md: 'h-2.5 w-2.5',
    lg: 'h-3 w-3',
    xl: 'h-3.5 w-3.5',
    '2xl': 'h-4 w-4'
  };

  const getInitials = (name) => {
    if (!name) return '?';
    return name
      .split(' ')
      .map(word => word[0])
      .join('')
      .substring(0, 2)
      .toUpperCase();
  };

  return (
    <div className={`relative inline-block ${className}`} {...props}>
      {src ? (
        <img
          src={src}
          alt={alt}
          className={`${sizes[size]} rounded-full object-cover ring-2 ring-white`}
          onError={(e) => {
            e.target.style.display = 'none';
            e.target.nextSibling.style.display = 'flex';
          }}
        />
      ) : null}
      
      <div 
        className={`${sizes[size]} rounded-full bg-gray-300 flex items-center justify-center text-gray-600 font-medium ring-2 ring-white ${src ? 'hidden' : 'flex'}`}
        style={{ fontSize: size === 'xs' || size === 'sm' ? '0.75rem' : '0.875rem' }}
      >
        {getInitials(fallback || alt)}
      </div>
      
      {online && (
        <span 
          className={`absolute bottom-0 right-0 ${statusSizes[size]} bg-emerald-400 border-2 border-white rounded-full`}
        />
      )}
    </div>
  );
};

export default Avatar;
